exercises.solution:
def F(x, y):
    return (x ** 2 - y ** 2, 2 * x * y)

def jacobian_fd(x, y, h):
    col_x = [(p - q) / (2 * h) for p, q in zip(F(x + h, y), F(x - h, y))]
    col_y = [(p - q) / (2 * h) for p, q in zip(F(x, y + h), F(x, y - h))]
    return [[col_x[0], col_y[0]], [col_x[1], col_y[1]]]
